# note-toggle.ps1 -- helper for Neovim's :Note command.
# GENERATED BY init.lua -- do not edit by hand, your changes will be overwritten.
#
# NOTE: this file is deliberately pure ASCII. PowerShell 5.1 reads a BOM-less
# file using the ANSI code page, which mangles UTF-8 and can silently swallow a
# closing brace or quote. All user-facing text lives on the Lua side instead.
#
# Why window handles and not pids: modern VS Code runs ONE main process that
# hosts every window, so all its windows share a pid. Only the HWND is unique.
#
# Usage:
#   -Mode launch -File <path> -Line <n> -Column <n> [-Reuse]
#       Record the current foreground window (the terminal), open the file in
#       VS Code, wait for the new window to show up and report its handle.
#       Output: OK <termHwnd> <vscodeHwnd> <confirmed>   or   ERR <reason>
#               confirmed=1 means the window title was seen to name the file,
#               so -Expect can safely be used when closing it later.
#   -Mode close -Hwnd <termHwnd> -Window <vscodeHwnd> [-Expect <basename>]
#       Verify the target really is a Code.exe window (and that its title
#       matches, when -Expect is given), send it WM_CLOSE, then bring the
#       terminal back to the foreground.
#       Output: OK / GONE / SKIP <title> / ERR <reason>

param(
  [Parameter(Mandatory = $true)]
  [ValidateSet('launch', 'close')]
  [string]$Mode,

  [string]$File = '',
  [int]$Line = 1,
  [int]$Column = 1,
  [switch]$Reuse,

  [long]$Hwnd = 0,
  [long]$Window = 0,
  [string]$Expect = '',
  [int]$TimeoutMs = 15000
)

$ErrorActionPreference = 'Stop'

# Report stdout as UTF-8 so window titles survive the trip back to Neovim.
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }

Add-Type -TypeDefinition @'
using System;
using System.Text;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;

public class NoteWin {
  delegate bool EnumProc(IntPtr h, IntPtr l);

  [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc cb, IntPtr l);
  [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] static extern bool IsWindow(IntPtr h);
  [DllImport("user32.dll")] static extern bool IsIconic(IntPtr h);
  [DllImport("user32.dll")] static extern bool ShowWindow(IntPtr h, int cmd);
  [DllImport("user32.dll")] static extern bool PostMessageW(IntPtr h, uint msg, IntPtr w, IntPtr l);
  [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] static extern bool AttachThreadInput(uint a, uint b, bool f);
  [DllImport("kernel32.dll")] static extern uint GetCurrentThreadId();
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);

  const uint WM_CLOSE = 0x0010;
  const int SW_RESTORE = 9;
  const string EMPTY = "";

  static string Title(IntPtr h) {
    var sb = new StringBuilder(512);
    GetWindowTextW(h, sb, 512);
    return sb.ToString();
  }

  static bool IsOfProcess(IntPtr h, string procName) {
    uint pid;
    GetWindowThreadProcessId(h, out pid);
    if (pid == 0) return false;
    try { return string.Equals(Process.GetProcessById((int)pid).ProcessName, procName, StringComparison.OrdinalIgnoreCase); }
    catch { return false; }
  }

  // "handle|title" for every visible top-level window owned by procName.
  public static string[] ListWindows(string procName) {
    var res = new List<string>();
    EnumWindows((h, l) => {
      if (!IsWindowVisible(h)) return true;
      if (!IsOfProcess(h, procName)) return true;
      string t = Title(h);
      if (t.Length == 0) return true;
      res.Add(h.ToInt64() + "|" + t);
      return true;
    }, IntPtr.Zero);
    return res.ToArray();
  }

  // Set difference is computed here on purpose: PowerShell unrolls arrays
  // returned into @(...), which silently breaks counting.
  public static string[] WindowsNotIn(string procName, string[] seen) {
    var set = new HashSet<string>();
    if (seen != null) foreach (var s in seen) set.Add(s);
    var res = new List<string>();
    foreach (var w in ListWindows(procName)) {
      if (!set.Contains(w)) res.Add(w);
    }
    return res.ToArray();
  }

  public static string HandleOf(string entry) { return entry.Substring(0, entry.IndexOf('|')); }

  public static string TitleOfEntry(string entry) { return entry.Substring(entry.IndexOf('|') + 1); }

  public static long Foreground() { return GetForegroundWindow().ToInt64(); }

  public static bool Exists(long h) { return h != 0 && IsWindow(new IntPtr(h)); }

  public static string TitleOf(long h) { return Exists(h) ? Title(new IntPtr(h)) : EMPTY; }

  public static bool BelongsTo(long h, string procName) {
    return Exists(h) && IsOfProcess(new IntPtr(h), procName);
  }

  // Close exactly this one window -- same as clicking its own X button, so VS
  // Code still prompts to save if the file was edited over there.
  public static bool CloseWindow(long h) {
    if (!Exists(h)) return false;
    return PostMessageW(new IntPtr(h), WM_CLOSE, IntPtr.Zero, IntPtr.Zero);
  }

  public static bool FocusWindow(long h) {
    if (!Exists(h)) return false;
    var w = new IntPtr(h);
    if (IsIconic(w)) ShowWindow(w, SW_RESTORE);

    // Windows only lets the foreground process steal focus. Attaching our input
    // queue to the current foreground thread lifts that restriction.
    uint fgPid;
    uint fgThread = GetWindowThreadProcessId(GetForegroundWindow(), out fgPid);
    uint myThread = GetCurrentThreadId();
    bool ok;
    if (fgThread != 0 && fgThread != myThread) {
      AttachThreadInput(myThread, fgThread, true);
      ok = SetForegroundWindow(w);
      AttachThreadInput(myThread, fgThread, false);
    } else {
      ok = SetForegroundWindow(w);
    }
    return ok;
  }
}
'@

if ($Mode -eq 'launch') {
  if (-not $File) { Write-Output 'ERR missing -File'; exit 1 }

  # 1. Remember which window is in the foreground right now (the terminal).
  $termHwnd = [NoteWin]::Foreground()

  # 2. Snapshot existing VS Code windows so the new one can be found by diff.
  [string[]]$before = [NoteWin]::ListWindows('Code')

  $codeArgs = @()
  if (-not $Reuse) { $codeArgs += '-n' }
  # --goto takes file:line:column, which puts the caret where nvim left it.
  $codeArgs += '--goto'
  $codeArgs += ('{0}:{1}:{2}' -f $File, $Line, $Column)

  try {
    Start-Process -FilePath 'code' -ArgumentList $codeArgs -ErrorAction Stop | Out-Null
  } catch {
    Write-Output ('ERR cannot launch code: ' + $_.Exception.Message)
    exit 1
  }

  # 3. Poll until the new window shows up AND its title names our file.
  #    Right after launch the title is still just "Visual Studio Code", so
  #    returning on first sight would hand back a handle we cannot verify.
  $basename = [System.IO.Path]::GetFileName($File)
  $deadline = (Get-Date).AddMilliseconds($TimeoutMs)
  $found = 0
  $confirmed = 0
  $fallback = 0
  while ((Get-Date) -lt $deadline) {
    [string[]]$fresh = [NoteWin]::WindowsNotIn('Code', $before)
    if ($fresh.Length -gt 0) {
      $hit = $fresh | Where-Object { [NoteWin]::TitleOfEntry($_).Contains($basename) } | Select-Object -First 1
      if ($hit) {
        $found = [long][NoteWin]::HandleOf($hit)
        $confirmed = 1
        break
      }
      if ($fallback -eq 0) { $fallback = [long][NoteWin]::HandleOf($fresh[0]) }
    }
    Start-Sleep -Milliseconds 150
  }
  if ($found -eq 0) { $found = $fallback }

  # handle 0     -> VS Code reused an existing window, or never showed up
  # confirmed 0  -> handle found but the title never matched before the timeout,
  #                 so the caller should not rely on a title check when closing
  Write-Output ('OK {0} {1} {2}' -f $termHwnd, $found, $confirmed)
  exit 0
}

if ($Mode -eq 'close') {
  $result = 'GONE'
  if ($Window -gt 0) {
    # A recycled handle could now point at an unrelated window, so re-check that
    # it is still owned by Code.exe before touching it.
    if ([NoteWin]::BelongsTo($Window, 'Code')) {
      $title = [NoteWin]::TitleOf($Window)
      # With -Expect, also require the title to name our file. Belt and braces
      # so a stale handle can never close one of your other VS Code windows.
      if ($Expect -eq '' -or $title.IndexOf($Expect, [StringComparison]::OrdinalIgnoreCase) -ge 0) {
        if ([NoteWin]::CloseWindow($Window)) { $result = 'OK' } else { $result = 'ERR PostMessage failed' }
        Start-Sleep -Milliseconds 350
      } else {
        $result = 'SKIP title mismatch: ' + $title
      }
    }
  }
  [NoteWin]::FocusWindow($Hwnd) | Out-Null
  Write-Output $result
  exit 0
}
